SELECT
FINPROD_ID id,
FINPROD_NAME text,
PROFIT_TYPE object
FROM
FIN_PRODUCT
WHERE P_FINPROD_ID IS NULL
AND to_char(MDATE,'yyyy-mm-dd') > #{vdate}

AND to_char(MDATE,'yyyy-mm-dd') > #{mdate}

AND PROFIT_TYPE <> #{profitType}


AND to_char(VDATE,'yyyy-mm-dd') <= #{vdate}

    AND FINPROD_NAME like '%' || #{search,jdbcType=VARCHAR} || '%'
